from rest_framework.decorators import api_view
from rest_framework.response import Response
from rest_framework import status


@api_view(["GET", "POST", "PUT", "PATCH", "DELETE"])
def hello(request):
    if request.method == "GET":
        return Response({"message": "دریافت شد", "method": "GET"})

    if request.method == "POST":
        return Response(
            {"message": "ساخته شد", "received": request.data},
            status=status.HTTP_201_CREATED,
        )

    if request.method == "PUT":
        return Response({"message": "جایگزین شد", "received": request.data})

    if request.method == "PATCH":
        return Response({"message": "ویرایش شد", "received": request.data})

    if request.method == "DELETE":
        return Response(status=status.HTTP_204_NO_CONTENT)

    # این خط هرگز اجرا نمی‌شود چون @api_view متدهای دیگر را رد می‌کند
    return Response(status=status.HTTP_405_METHOD_NOT_ALLOWED)

from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status


class HelloView(APIView):
    def get(self, request):
        return Response({"message": "دریافت شد", "method": "GET"})

    def post(self, request):
        return Response(
            {"message": "ساخته شد", "received": request.data},
            status=status.HTTP_201_CREATED,
        )

    def put(self, request):
        return Response({"message": "جایگزین شد", "received": request.data})

    def patch(self, request):
        return Response({"message": "ویرایش شد", "received": request.data})

    def delete(self, request):
        return Response(status=status.HTTP_204_NO_CONTENT)

