# catalog/views.py
from rest_framework.decorators import api_view
from rest_framework.response import Response


@api_view(["GET", "POST"])
def welcome(request):
    if request.method == "GET":
        return Response({"message": "خوش آمدید"})

    name = request.data.get("name", "مهمان")
    return Response({"greeting": f"سلام، {name}!"})
```

